import dataclasses

RUNS = [0]


@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32), *, s=2.0):
    RUNS[0] += 1
    for c in kt.par(2, on=kt.vc):
        v = kt.unpack(kt.load(x[c * 4 : c * 4 + 4, :]))
        kt.store(y[c * 4 : c * 4 + 4, :], v * s)


def facts():
    g = {"x": TY.TensorSpec.make((8, 32))}
    a = k.trace(g, machine=MACHINE)
    b = k.trace(g, machine=MACHINE)
    runs = RUNS[0]
    c = k.trace(g, machine=MACHINE, s=3.0)
    two = dataclasses.replace(MACHINE, nodes=2)
    d = k.trace(g, machine=two)
    return {
        "same": a is b,
        "runs": runs,
        "other_const": c is a,
        "other_machine": d is a,
        "runs_after": RUNS[0],
    }
